def find_max_length_subarray(arr):
    n = len(arr)

    # Initialize dp array where dp[i] represents length of longest subsequence ending at index i
    dp = [1] * n

    # Fill dp[] from left to right
    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= 1:
                dp[i] = max(dp[i], dp[j] + 1)

    # Return maximum value in dp[]
    return max(dp)

# Test cases
print(find_max_length_subarray([2, 5, 6, 3, 7, 6, 5, 8]))  # Expected output: 5
